selector_to_html = {"a[href=\"#platform-abstraction-and-multi-chip-training\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Platform Abstraction and Multi-Chip Training<a class=\"headerlink\" href=\"#platform-abstraction-and-multi-chip-training\" title=\"Link to this heading\">#</a></h1><p>verl-FL replaces the hard-coded <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.cuda</span></code> calls of upstream verl with a platform abstraction layer, and integrates the FlagOS training engines, so the same RL post-training script runs on NVIDIA, Huawei Ascend, MetaX (MACA), Moore Threads (MUSA), and CPU. This page describes the abstraction, the engine plugins, and the validated end-to-end workflows.</p>", "a[href=\"#environment-requirements\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Environment requirements<a class=\"headerlink\" href=\"#environment-requirements\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#optional-verify-flagcx-cross-node-communication-first\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">(Optional) Verify FlagCX cross-node communication first<a class=\"headerlink\" href=\"#optional-verify-flagcx-cross-node-communication-first\" title=\"Link to this heading\">#</a></h3><p>Before a full run you can check that the two nodes communicate over FlagCX, without Ray or verl-FL. On the MUSA node (rank 0):</p>", "a[href=\"#engine-plugin-architecture\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Engine Plugin Architecture<a class=\"headerlink\" href=\"#engine-plugin-architecture\" title=\"Link to this heading\">#</a></h2><p>Training engines are pluggable and registered per device:</p>", "a[href=\"#platform-abstraction-layer\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Platform Abstraction Layer<a class=\"headerlink\" href=\"#platform-abstraction-layer\" title=\"Link to this heading\">#</a></h2><p>The abstraction lives under <code class=\"docutils literal notranslate\"><span class=\"pre\">verl/plugin/platform/</span></code> and follows the Strategy Pattern:</p>", "a[href=\"#step-2-launch-heterogeneous-grpo-training\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Step 2 \u2014 Launch heterogeneous GRPO training<a class=\"headerlink\" href=\"#step-2-launch-heterogeneous-grpo-training\" title=\"Link to this heading\">#</a></h3><p>Point <code class=\"docutils literal notranslate\"><span class=\"pre\">config/one_step_off_ppo_trainer.yaml</span></code> at your local data and model:</p>", "a[href=\"#step-1-start-the-ray-cluster\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Step 1 \u2014 Start the Ray cluster<a class=\"headerlink\" href=\"#step-1-start-the-ray-cluster\" title=\"Link to this heading\">#</a></h3><p>On the MUSA node (head, handles rollout):</p>", "a[href=\"#adding-a-new-backend\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Adding a New Backend<a class=\"headerlink\" href=\"#adding-a-new-backend\" title=\"Link to this heading\">#</a></h2><p>See <code class=\"docutils literal notranslate\"><span class=\"pre\">verl/plugin/platform/README.md</span></code> in the repository for a fully annotated template.</p>", "a[href=\"#heterogeneous-training-with-flagcx\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Heterogeneous Training with FlagCX<a class=\"headerlink\" href=\"#heterogeneous-training-with-flagcx\" title=\"Link to this heading\">#</a></h2><p><a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagCX\">FlagCX</a> is the unified cross-vendor communication backend. It lets one cluster mix accelerators: NVIDIA nodes run actor/critic (FSDP) while Moore Threads MUSA nodes run rollout (vLLM), with weight synchronization and device isolation handled through the Ray runtime context.</p>", "a[href=\"#what-a-validated-run-looks-like\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">What a Validated Run Looks Like<a class=\"headerlink\" href=\"#what-a-validated-run-looks-like\" title=\"Link to this heading\">#</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
